fn is_palindrome(text: Vec<char>) -> bool {
    let n = text.len();
    let mut i = 0;
    
    while i < n / 2 {
        let left_char = to_ascii_lowercase(text[i]);
        let right_char = to_ascii_lowercase(text[n - 1 - i]);
        
        if left_char != right_char {
            return false;
        }
        
        i += 1;
    }
    
    true
}

fn to_ascii_lowercase(c: char) -> char {
    if c >= 'A' && c <= 'Z' {
        ((c as u8) + 32) as char
    } else {
        c
    }
}